// ==========================
// 🔹 1. OBTENER RESPUESTA OPENAI
// ==========================
let raw = $input.first().json['0'].content[0].text;

raw = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// ==========================
// 🔹 2. PARSEAR JSON
// ==========================
let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {};
}

// ==========================
// 🔹 3. FUNCIONES UTILES
// ==========================
const normalize = (str) =>
  str?.toLowerCase()
     .normalize("NFD")
     .replace(/[\u0300-\u036f]/g, "") // quitar tildes
     .trim();

// ==========================
// 🔹 4. NORMALIZAR DATOS OCR
// ==========================
const comprobanteOCR = parsed.comprobante?.replace(/\s/g, '') || null;
const montoOCR = parsed.monto ?? null;
const bancoOCR = normalize(parsed.banco);
const fechaOCR = parsed.fecha || null;
const titularOCR = normalize(parsed.titular);

// ==========================
// 🔹 5. DATOS DEL WEBHOOK
// ==========================
const webhook = $('Verificador').first().json.body;

const comprobanteWebhook = webhook.numcomprobante?.replace(/\s/g, '');
const montoWebhook = webhook.valor;
const bancoWebhook = normalize(webhook.banco?.nombreban);
const titularWebhook = normalize(webhook.banco?.propietarioban);
const fechaWebhook = webhook.created_at;

// ==========================
// 🔹 6. VALIDACIONES
// ==========================
let aprobado = true;
let errores = [];

// ✔ comprobante
if (!comprobanteOCR || comprobanteOCR !== comprobanteWebhook) {
  aprobado = false;
  errores.push("Comprobante no coincide");
}

// ✔ comprobante sospechoso (ej: 111111)
if (comprobanteOCR && /^(\d)\1+$/.test(comprobanteOCR)) {
  aprobado = false;
  errores.push("Comprobante sospechoso");
}

// ✔ monto
if (montoOCR === null || Math.abs(montoOCR - montoWebhook) > 0.01) {
  aprobado = false;
  errores.push("Monto no coincide");
}

// ✔ banco (dinámico 🔥)
if (!bancoOCR || !bancoOCR.includes(bancoWebhook)) {
  aprobado = false;
  errores.push("Banco no coincide");
}

// ==========================
// ✔ titular (ULTRA ROBUSTO 🔥)
// ==========================
const splitWords = (str) => normalize(str).split(/\s+/).filter(Boolean);

const ocrWords = splitWords(titularOCR);
const webhookWords = splitWords(titularWebhook);

// evitar duplicados
const unique = arr => [...new Set(arr)];

const ocrSet = unique(ocrWords);
const webhookSet = unique(webhookWords);

// contar coincidencias reales
let matches = 0;

for (let w of webhookSet) {
  for (let o of ocrSet) {

    if (o === w) {
      matches++;
      break;
    }

    // match parcial fuerte (mínimo 4 letras)
    if (o.length >= 4 && w.length >= 4) {
      if (o.includes(w.slice(0,4)) || w.includes(o.slice(0,4))) {
        matches++;
        break;
      }
    }
  }
}

// porcentaje de match
const ratio = matches / webhookSet.length;

// regla inteligente
if (ratio < 0.6) {
  aprobado = false;
  errores.push(`Titular no coincide (${Math.round(ratio * 100)}%)`);
}

// ==========================
// ✔ fecha (INTELIGENTE 🔥)
// ==========================
if (fechaOCR) {

  const toDateOnly = (f) => {
    const d = new Date(f);
    return new Date(d.getFullYear(), d.getMonth(), d.getDate());
  };

  const fOCR = toDateOnly(fechaOCR);
  const fWEB = toDateOnly(fechaWebhook);

  const diffDias = Math.abs(
    (fWEB - fOCR) / (1000 * 60 * 60 * 24)
  );

  // detectar fin de semana
  const isWeekend = (date) => {
    const day = date.getDay();
    return day === 0 || day === 6;
  };

  let maxDias = 1;

  // si cae en finde → ampliar ventana
  if (isWeekend(fOCR) || isWeekend(fWEB)) {
    maxDias = 3;
  }

  // tolerancia adicional por banca (opcional)
  maxDias = Math.max(maxDias, 2);

  if (diffDias > maxDias) {
    aprobado = false;
    errores.push(`Fecha fuera de rango (${diffDias} días)`);
  }

} else {
  aprobado = false;
  errores.push("Fecha no detectada");
}

// ==========================
// 🚨 7. ANTIFRAUDE (IA)
// ==========================

// ilegible
if (parsed.legible === false) {
  aprobado = false;
  errores.push("Imagen no legible");
}

// borroso
if (parsed.borroso === true) {
  aprobado = false;
  errores.push("Imagen borrosa");
}

// editado
if (parsed.editado === true) {
  aprobado = false;
  errores.push("Posible edición");
}

// no real
if (parsed.realista === false) {
  aprobado = false;
  errores.push("No parece real");
}

// baja confianza
if (parsed.confianza !== undefined && parsed.confianza < 70) {
  aprobado = false;
  errores.push("Baja confianza IA");
}

// ==========================
// 🧠 8. SCORE ANTIFRAUDE (PRO 🔥)
// ==========================
let score = 100;

if (parsed.borroso) score -= 20;
if (parsed.editado) score -= 40;
if (!parsed.realista) score -= 40;
if (!parsed.legible) score -= 30;

if (score < 60) {
  aprobado = false;
  errores.push("Score antifraude bajo");
}

// ==========================
// 🧾 9. RESULTADO FINAL
// ==========================
return [
  {
    json: {
      aprobado,
      errores: errores.join(", "),
      score,

      data_extraida: {
        comprobante: comprobanteOCR,
        monto: montoOCR,
        banco: bancoOCR,
        fecha: fechaOCR,
        titular: titularOCR,
        titularWebhook: titularWebhook
      },

      idrec: webhook.idrec,
      raw
    }
  }
];

