// ==========================
// 🔹 1. OBTENER STRING DEL AGENTE
// ==========================
let raw = $json.output || "";

// limpiar markdown si viene con ```json
raw = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// ==========================
// 🔹 2. PARSEAR JSON REAL
// ==========================
let data;

try {
  data = JSON.parse(raw);
} catch (e) {
  data = {};
}

// ==========================
// 🔹 3. LIMPIAR TEXTO WHATSAPP
// ==========================
let texto = data.reply_text || "";

// convertir \n → salto real
texto = texto.replace(/\\n/g, '\n');

// limpiar saltos excesivos
texto = texto.replace(/\n{3,}/g, '\n\n').trim();

// ==========================
// 🔹 4. HARDEN WHATSAPP
// ==========================
if (texto.length > 4000) {
  texto = texto.substring(0, 3900) + "\n\n... (mensaje recortado)";
}

// ==========================
// 🔹 5. FLAGS
// ==========================
const accion = data.accion_requerida === true;
const escalar = data.escalar_humano === true;

// ==========================
// 🔹 6. OUTPUT FINAL
// ==========================
return [
  {
    json: {
      mensaje: texto,

      meta: {
        subagente: data.subagente_codigo || null,
        estado: data.accion_tipo || null,
        confianza: data.confianza || 0
      },

      control: {
        requiere_accion: accion,
        accion_tipo: data.accion_tipo || null,
        accion_payload: data.accion_payload || null,

        escalar_humano: escalar,
        motivo_humano: data.motivo_humano || null
      }
    }
  }
];

